      {
        "factor": "Escalation and persistence of war dynamics increasing exposure to chemical-weapons-capable conditions",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Longer, more intense fighting raises opportunities and incentives for chemical-weapon deployment."
      },
      {
        "factor": "Attribution uncertainty reducing deterrence against chemical weapons use",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Ambiguity about who is responsible lowers expected costs, contributing to higher risk."
